import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.I6s8z2kk.js";const m=JSON.parse('{"title":"Homepage content","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/homepage.md","filePath":"dev/domain/homepage.md"}'),d={name:"dev/domain/homepage.md"};function i(r,e,s,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="homepage-content" tabindex="-1">Homepage content <a class="header-anchor" href="#homepage-content" aria-label="Permalink to &quot;Homepage content&quot;">​</a></h1><p>The <strong>Homepage</strong> module builds the client home screen from sections, banners and curated items.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><p><code>HomeSection</code> types are <strong>immutable after creation</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Shows</th></tr></thead><tbody><tr><td><code>banner_carousel</code></td><td>Banners (the only type that accepts banners)</td></tr><tr><td><code>curated_centers</code></td><td>Centers picked by an admin, in order</td></tr><tr><td><code>curated_services</code></td><td>Services picked by an admin, in order</td></tr><tr><td><code>curated_promotions</code></td><td>Running promotions picked by an admin</td></tr><tr><td><code>curated_campaigns</code></td><td>Running campaigns picked by an admin</td></tr><tr><td><code>top_centers</code></td><td>Centers by popularity, or nearest first when <code>lat</code> and <code>lng</code> are sent</td></tr></tbody></table><p>Items are stored as <code>HomeSectionItem</code> rows with optional <code>starts_at</code> and <code>ends_at</code>.</p><h2 id="what-clients-see" tabindex="-1">What clients see <a class="header-anchor" href="#what-clients-see" aria-label="Permalink to &quot;What clients see&quot;">​</a></h2><p>Sections and banners must be <strong>published</strong> and inside <code>[starts_at, ends_at)</code>. Within them:</p><ul><li>Centers are visible and active.</li><li>Services are <code>ACTIVE</code> and belong to visible centers.</li><li>Promotions are active and within their limits.</li><li>Campaigns are running.</li></ul><p>Sections with nothing to show are dropped. A section that is not visible answers 404.</p><h2 id="display-prices" tabindex="-1">Display prices <a class="header-anchor" href="#display-prices" aria-label="Permalink to &quot;Display prices&quot;">​</a></h2><p>Curated services carry <code>start_price</code> and <code>display_price</code> (see <a href="./promotions#display-prices">Promotions</a>). The builder computes them for the visible page of items with one <code>ServicePriceDisplay::forServices()</code> call, and <code>HomeServiceResource::withPrices()</code> writes them out.</p><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><p>Home payloads are cached under a <strong>versioned key</strong>. Register every model that home content displays in <code>flushContentOnChanges()</code> so its save, delete or restore bumps the version. The cache also expires at the next boundary (a section or item start or end time), so scheduled content appears on time.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p>Content analytics are <strong>aggregate-only</strong> per <code>(day, entity)</code> with no personal data. Events for unknown entities are dropped. Clients send events to <code>clients/home/events</code>; admins read them at <code>admin/analytics/home-content</code>.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Endpoints</th></tr></thead><tbody><tr><td>Client</td><td><code>clients/home</code>, <code>clients/home/sections/{key}</code> (paged), <code>clients/home/events</code></td></tr><tr><td>Admin</td><td><code>admin/home-sections</code> CRUD, <code>reorder</code>, <code>item-candidates</code>, <code>items</code>; <code>admin/banners</code> CRUD. Needs <code>homepage.manage</code>.</td></tr></tbody></table>',18)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
